- Education Level: {{ $('Normalize & Prepare Context').item.json.patient_full_object.tcm_social_needs?.education_level }}
- Marital Status: {{ $('Normalize & Prepare Context').item.json.patient_full_object.tcm_social_needs?.marital_status }}
